def find_connected_component(grid, start_r, start_c, include_inside=True):
    """Find connected region of 1s including interior"""
    visited = set()
    q = deque([(start_r, start_c)])

    directions = [(-1,0), (1,0), (0,-1), (0,1)]
    while q:
        r, c = q.popleft()
        if (r,c) in visited:
            continue
        visited.add((r,c))

        # Check bounds and if cell is part of frame (either 1 or inside frame)
        if r < 0 or r >= len(grid) or c < 0 or c >= len(grid[r]):
            continue

        if grid[r][c] == 1:
            pass  # Continue to neighbors
        else:
            continue  # Skip non-frame cells

