            nr, nc = r + dr, c + dc
            if (nr, nc) not in visited:
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[nr]):
                    if grid[nr][nc] == 1:
                        q.append((nr, nc))

    return visited

