demo_out = G['Demo pair 1 output']

# Get full frame bounds
frame_cells = set()
for r in range(len(demo_in)):
    for c in range(len(demo_in[r])):
        if demo_in[r][c] == 1:
            frame_cells.add((r,c))
rows = [cell[0] for cell in frame_cells]
cols = [cell[1] for cell in frame_cells]
min_r, max_r = min(rows), max(rows)
min_c, max_c = min(cols), max(cols)

full_frame = [row[min_c:max_c+1] for row in demo_in[min_r:max_r+1]]
h, w = len(full_frame), len(full_frame[0])

print(f"Full frame: {h}x{w}")
print("Full frame:")
for row in full_frame: print(row)

# Try various combinations: transpose + operations
transposed = [[full_frame[r][c] for r in range(h)] for c in range(w)]
print("\nTranspose:")
for row in transposed: print(row)

# Transpose then rotate 180
def rotate_180(grid):
    h, w = len(grid), len(grid[0])
    return [[grid[h-1-i][w-1-j] for j in range(w)] for i in range(h)]

rotated_transposed = rotate_180(transposed)
print("\nTranspose then 180°:")
for row in rotated_transposed: print(row)

# Compare with expected
print("\nExpected:")
for row in demo_out: print(row)

# Check differences
diff_count = 0
for r in range(10):
    for c in range(9):
        if rotated_transposed[r][c] != demo_out[r][c]:
            diff_count += 1
            print(f"Diff ({r},{c}): got {rotated_transposed[r][c]}, expected {demo_out[r][c]}")
print(f"\nDifference count: {diff_count}")
